{
  "id": 49,
  "knowledge": "Peer Mimicry Suspicion",
  "description": "Flags traders whose behavior closely matches peers but deviates little from known patterns, potentially mimicking a risky group.",
  "definition": "A trader with a low 'Pattern Anomaly Score' (e.g., < 0.1) BUT a high peer correlation score (e.g., > 0.7)."
}

{
  "id": 28,
  "knowledge": "Pattern Similarity Score Context",
  "description": "Provides context for the pattern similarity score, comparing trading to known illicit behaviors.",
  "definition": "A score from 0-1. Values near 1 indicate high similarity to known illicit trading patterns. Values near 0 indicate patterns do not strongly match known manipulative techniques."
}

{
  "id": 73,
  "knowledge": "Peer Correlation Z-Score",
  "description": "A normalized score indicating how many standard deviations an individual record's peer correlation is away from the average peer correlation of all traders within the same trader category. Used for standardized comparison across different peer groups.",
  "definition": "Z-Score = (Individual Peer Correlation - Average Peer Correlation for the Trader's Category) / Standard Deviation of Peer Correlation for the Trader's Category. The score is 0 if the standard deviation is zero or not applicable."
}

{
  "id": 36,
  "knowledge": "Aggressive Trading Intensity (ATI)",
  "description": "Measures intensity by combining high turnover, leverage, and order modification frequency.",
  "definition": "ATI = 'Daily Turnover Rate' \\times 'Trader Leverage Exposure' \\times 'Order Modification Intensity'."
}

{
  "id": 1,
  "knowledge": "Order Modification Intensity (OMI)",
  "description": "Measures how frequently a trader modifies orders relative to their cancellation rate.",
  "definition": "OMI = \\frac{\\text{Order Modification Frequency}}{1 - \\text{Order Cancellation Percentage}} \\text{ (undefined if cancellation percentage is 1)}"
}

{
  "id": 54,
  "knowledge": "Aggressive Suspicion Score (ASS)",
  "description": "Combines overall suspicious activity index with aggressive trading intensity, identifying traders who are both suspicious and trade aggressively.",
  "definition": "ASS = 'Suspicious Activity Index' \\times 'Aggressive Trading Intensity'"
}

{
  "id": 56,
  "knowledge": "Market-Agnostic Suspicion Index (MASI)",
  "description": "Combines the general suspicion index with market-adjusted pattern anomaly, focusing on suspicious activity independent of market moves.",
  "definition": "MASI = ('Suspicious Activity Index' + 'Market-Adjusted Pattern Anomaly') / 2"
}

{
  "id": 39,
  "knowledge": "Market-Adjusted Pattern Anomaly (MAPA)",
  "description": "Calculates pattern anomaly score adjusted for market correlation, highlighting non-market related deviations.",
  "definition": "MAPA = 'Pattern Anomaly Score' \\times (1 - \\text{Market Correlation})"
}

{
  "id": 52,
  "knowledge": "Unique Pattern Deviation Ratio (UPDR)",
  "description": "Measures the ratio of unique pattern deviation (anomaly) to the similarity with known illicit patterns, indicating how unusual the potentially illicit behavior is.",
  "definition": "UPDR = \\frac{\\text{'Pattern Anomaly Score'}}{\\text{Max}(0.01, \\text{'Pattern Similarity Score'})}"
}

